library file
```rust
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Plan {
    pub task_id: String,
    pub node: String,
    pub promoted: bool,
    pub signals: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NodeState {
    cost: u32,
    capacity: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Edge {
    from: String,
    to: String,
    ramp: bool,
}

pub struct Scheduler {
    nodes: HashMap<String, NodeState>,
    edges: Vec<Edge>,
    next_thread_id: u32,
}

impl Scheduler {
    pub fn new() -> Self {
        Scheduler {
            nodes: HashMap::new(),
            edges: Vec::new(),
            next_thread_id: 1,
        }
    }

    pub fn add_node(&mut self, id: &str, cost: u32, capacity: usize) {
        self.nodes.insert(
            id.to_string(),
            NodeState {
                cost,
                capacity,
            },
        );
    }

    pub fn add_ramp(&mut self, from: &str, to: &str) {
        self.edges.push(Edge {
            from: from.to_string(),
            to: to.to_string(),
            ramp: true,
        });
    }

    pub fn schedule(&self, task_id: &str, candidates: &[&str], max_cost: u32) -> Option<Plan> {
        let mut skipped_full_node: Option<String> = None;
        let mut promoted = false;
        let mut signals: Vec<String> = Vec::new();

        for candidate in candidates {
            let node_state = self.nodes.get(*candidate)?;

            if node_state.cost > max_cost {
                continue;
            }

            if node_state.capacity == 0 {
                signals.push(format!("backpressure:{}", candidate));
                skipped_full_node = Some(candidate.to_string());
                continue;
            }

            // Check for promotion
            if let Some(skipped) = &skipped_full_node {
                if self.edges.iter().any(|edge| 
                    edge.from == *skipped && edge.to == *candidate && edge.ramp
                ) {
                    promoted = true;
                }
            }

            return Some(Plan {
                task_id: task_id.to_string(),
                node: candidate.to_string(),
                promoted,
                signals,
            });
        }

        None
    }
}
