```rust
use std::io::Read;
use rust_ordo_suite::{Scheduler, Plan};

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();

    let mut scheduler = Scheduler::new();

    for line in input.lines() {
        let parts: Vec<&str> = line.trim().split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }

        match parts[0] {
            "node" => {
                if parts.len() != 4 {
                    eprintln!("Invalid node command");
                    std::process::exit(1);
                }
                let name = parts[1];
                let cost: u32 = parts[2].parse().expect("Cost must be a number");
                let capacity: usize = parts[3].parse().expect("Capacity must be a number");
                scheduler.add_node(name, cost, capacity);
            },
            "ramp" => {
                if parts.len() != 3 {
                    eprintln!("Invalid ramp command");
                    std::process::exit(1);
                }
                let from = parts[1];
                let to = parts[2];
                scheduler.add_ramp(from, to);
            },
            "schedule" => {
                if parts.len() < 4 {
                    eprintln!("Invalid schedule command");
                    std::process::exit(1);
                }
                let task_id = parts[1];
                let max_cost: u32 = parts[2].parse().expect("Budget must be a number");
                let candidates: Vec<&str> = parts.iter().skip(3).map(|s| *s).collect();

                if let Some(plan) = scheduler.schedule(task_id, &candidates, max_cost) {
                    print_plan(&plan);
                }
            },
            _ => {
                eprintln!("Unknown command: {}", parts[0]);
                std::process::exit(1);
            }
        }
    }
}

fn print_plan(plan: &Plan) {
    let signals_str = if plan.signals.is_empty() {
        "none".to_string()
    } else {
        plan.signals.join(",")
    };

    println!(
        "task={} node={} promoted={} signals={}",
        plan.task_id,
        plan.node,
        plan.promoted,
        signals_str
    );
}
```

