use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct LedgerReport {
    pub total: u32,
    pub accepted: bool,
    pub route: Vec<String>,
}

#[derive(Debug, Default)]
pub struct CostLedger {
    costs: HashMap<String, u32>,
    route: Vec<String>,
}

impl CostLedger {
    pub fn new() -> Self {
        CostLedger::default()
    }

    pub fn charge(&mut self, node: &str, cost: u32) {
        self.costs.insert(node.to_string(), cost);
        self.route.push(node.to_string());
    }

    pub fn report(&self, budget: u32) -> LedgerReport {
        let total = self
            .route
            .iter()
            .map(|node| self.costs.get(node).copied().unwrap_or(0))
            .sum();
        let accepted = total <= budget;
        LedgerReport {
            total,
            accepted,
            route: self.route.clone(),
        }
    }
}
