use std::collections::{HashMap, VecDeque};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Message {
    pub topic: String,
    pub payload: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Trace {
    pub thread_id: usize,
    pub path: Vec<String>,
    pub promoted: bool,
    pub signals: Vec<String>,
}

#[derive(Debug, Clone)]
struct NodeState {
    capacity: usize,
    cost: u32,
}

#[derive(Debug, Clone)]
struct Edge {
    from: String,
    to: String,
    ramp: bool,
}

pub struct OrdoRuntime {
    nodes: HashMap<String, NodeState>,
    edges: Vec<Edge>,
    next_thread_id: usize,
}

impl OrdoRuntime {
    pub fn new() -> Self {
        OrdoRuntime {
            nodes: HashMap::new(),
            edges: Vec::new(),
            next_thread_id: 1,
        }
    }

    pub fn add_node(&mut self, id: &str) {
        self.nodes.insert(id.to_string(), NodeState {
            capacity: usize::MAX,
            cost: 0,
        });
    }

    pub fn connect(&mut self, from: &str, to: &str) {
        self.edges.push(Edge {
            from: from.to_string(),
            to: to.to_string(),
            ramp: false,
        });
    }

    pub fn add_ramp(&mut self, from: &str, to: &str) {
        self.edges.push(Edge {
            from: from.to_string(),
            to: to.to_string(),
            ramp: true,
        });
    }

    pub fn set_capacity(&mut self, node: &str, capacity: usize) {
        if let Some(state) = self.nodes.get_mut(node) {
            state.capacity = capacity;
        }
    }

    pub fn set_cost(&mut self, node: &str, cost: u32) {
        if let Some(state) = self.nodes.get_mut(node) {
            state.cost = cost;
        }
    }

    pub fn preload_targets(&self, node: &str) -> Vec<String> {
        self.edges.iter()
            .filter(|edge| edge.from == node)
            .map(|edge| edge.to.clone())
            .collect()
    }

    pub fn route_for_budget(&self, candidates: &[&str], max_cost: u32) -> Option<String> {
        for &candidate in candidates {
            if let Some(state) = self.nodes.get(candidate) {
                if state.cost <= max_cost {
                    return Some(candidate.to_string());
                }
            }
        }
        None
    }

    pub fn publish(&mut self, from: &str, topic: &str, payload: &str) -> Trace {
        let thread_id = self.next_thread_id;
        self.next_thread_id += 1;

        let mut path = Vec::new();
        let mut signals = Vec::new();
        let mut promoted = false;

        let mut current = from.to_string();
        loop {
            path.push(current.clone());

            if let Some(state) = self.nodes.get(&current) {
                if state.capacity == 0 {
                    signals.push(format!("backpressure:{}", current));
                }
            }

            let edge = self.edges.iter().find(|edge| edge.from == current).cloned();
            match edge {
                Some(edge) => {
                    if edge.ramp { promoted = true; }
                    current = edge.to.clone();
                }
                None => break,
            }
        }

        Trace {
            thread_id,
            path,
            promoted,
            signals,
        }
    }
}
