use std::collections::{HashMap, HashSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SignalTrace {
    pub kind: String,
    pub origin: String,
    pub affected: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SignalMesh {
    nodes: HashMap<String, usize>,
    layers: Vec<Vec<String>>,
}

impl SignalMesh {
    pub fn new() -> Self {
        SignalMesh {
            nodes: HashMap::new(),
            layers: Vec::new(),
        }
    }

    pub fn add_node(&mut self, name: &str, layer: usize) {
        self.nodes.insert(name.to_string(), layer);
        while self.layers.len() <= layer {
            self.layers.push(Vec::new());
        }
        self.layers[layer].push(name.to_string());
    }

    pub fn vertical(&self, origin: &str) -> SignalTrace {
        let origin_layer = *self.nodes.get(origin).expect("origin node must exist");
        let mut affected = vec![origin.to_string()];
        for (layer_idx, layer) in self.layers.iter().enumerate() {
            if layer_idx > origin_layer {
                affected.extend(layer.iter().cloned());
            }
        }

        SignalTrace {
            kind: "vertical".to_string(),
            origin: origin.to_string(),
            affected,
        }
    }

    pub fn horizontal(&self, origin: &str) -> SignalTrace {
        let origin_layer = *self.nodes.get(origin).expect("origin node must exist");
        let mut affected = Vec::new();
        if let Some(layer) = self.layers.get(origin_layer) {
            for node in layer {
                if node != origin {
                    affected.push(node.clone());
                }
            }
        }

        SignalTrace {
            kind: "horizontal".to_string(),
            origin: origin.to_string(),
            affected,
        }
    }

    pub fn propagate(&self, trace: &SignalTrace) -> SignalTrace {
        match trace.kind.as_str() {
            "vertical" => self.vertical(&trace.origin),
            "horizontal" => self.horizontal(&trace.origin),
            _ => unreachable!(),
        }
    }
}
