use std::io::{self, BufRead};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdin = io::stdin();
    let mut workflow = rust_ordo_ext::Workflow::new();

    for line in stdin.lock().lines() {
        let input = line?;
        let parts: Vec<&str> = input.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }

        match parts[0] {
            "connect" => {
                if parts.len() >= 3 {
                    workflow.connect(parts[1], parts[2]);
                }
            }
            "serialize" => {
                println!("workflow={}", workflow.serialize());
            }
            "parse" => {
                if parts.len() >= 2 {
                    workflow = rust_ordo_ext::Workflow::parse(parts[1]);
                }
            }
            _ => {}
        }
    }

    Ok(())
}
